// app/firebase-diagnostic-page.jsx  (or pages/firebase-diagnostic-page.jsx)
"use client";

import React, { useEffect, useState } from "react";
import { initializeApp, getApps, getApp } from "firebase/app";
import {
  getAuth,
  signInAnonymously,
  signInWithCustomToken,
  onAuthStateChanged,
} from "firebase/auth";
import { getFirestore } from "firebase/firestore";

/* --- small inline icon --- */
const AlertTriangleIcon = (props) => (
  <svg
    {...props}
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    className="w-6 h-6"
  >
    <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
    <line x1="12" y1="9" x2="12" y2="13" />
    <line x1="12" y1="17" x2="12.01" y2="17" />
  </svg>
);

const StatusItem = ({ label, status, detail, isCritical = false }) => {
  const colorClass = isCritical
    ? "border-red-600 text-red-800 bg-red-100 font-bold"
    : "border-gray-400 text-gray-700 bg-gray-50";

  return (
    <li
      className={`p-4 rounded-lg border-2 ${colorClass} transition-all duration-300`}
    >
      <div className="flex items-center justify-between">
        <span className="font-semibold">{label}</span>
        <div className="flex items-center space-x-2">
          {isCritical && <AlertTriangleIcon className="w-5 h-5 text-red-600" />}
          <span
            className={`font-bold text-sm ${
              isCritical ? "text-red-600" : "text-gray-500"
            }`}
          >
            {status}
          </span>
        </div>
      </div>
      {detail && (
        <p
          className={`text-xs mt-2 break-all ${
            isCritical ? "text-red-700" : "text-gray-500"
          }`}
        >
          {detail}
        </p>
      )}
    </li>
  );
};

export default function FirebaseDiagnosticPage() {
  const [statuses, setStatuses] = useState({
    appId: { status: "未確認", detail: "", isCritical: false },
    config: { status: "未確認", detail: "", isCritical: false },
    authToken: { status: "未確認", detail: "", isCritical: false },
    init: { status: "未確認", detail: "", isCritical: false },
    auth: { status: "未確認", detail: "", isCritical: false },
    firestore: { status: "未確認", detail: "", isCritical: false },
  });

  useEffect(() => {
    // 1) build config from NEXT_PUBLIC_ env
    const cfg = {
      apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY ?? "",
      authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN ?? "",
      projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? "",
      storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET ?? "",
      messagingSenderId:
        process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID ?? "",
      appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID ?? "",
    };

    // set __app_id fallback for legacy diagnostic compatibility
    try {
      const appId = cfg.appId || "default-app-id";
      (window as any).__app_id = appId;
      setStatuses((s) => ({
        ...s,
        appId: {
          status: cfg.appId ? "読み取り成功" : "代替処理",
          detail: cfg.appId
            ? `appId=${cfg.appId}`
            : `未定義。アプリケーションIDは「${appId}」としてフォールバック。`,
          isCritical: false,
        },
      }));
    } catch (e) {
      // ignore
    }

    // 2) inject __firebase_config for compatibility with old diagnostics
    if (cfg.apiKey && cfg.authDomain && cfg.projectId) {
      try {
        (window as any).__firebase_config = JSON.stringify(cfg);
        setStatuses((s) => ({
          ...s,
          config: {
            status: "読み取り成功",
            detail: "process.env から Firebase 設定を注入しました。",
            isCritical: false,
          },
        }));
      } catch (e) {
        setStatuses((s) => ({
          ...s,
          config: {
            status: "失敗/欠落",
            detail: `__firebase_config 注入に失敗: ${String(e)}`,
            isCritical: true,
          },
        }));
      }
    } else {
      setStatuses((s) => ({
        ...s,
        config: {
          status: "失敗/欠落",
          detail:
            "NEXT_PUBLIC_FIREBASE_* が不足しています。env を確認してください。",
          isCritical: true,
        },
      }));
    }

    // 3) optional initial token from env (if you set one for testing)
    const initialToken = process.env.NEXT_PUBLIC_INITIAL_AUTH_TOKEN ?? null;
    if (initialToken) {
      (window as any).__initial_auth_token = initialToken;
      setStatuses((s) => ({
        ...s,
        authToken: {
          status: "読み取り成功",
          detail:
            "NEXT_PUBLIC_INITIAL_AUTH_TOKEN からトークンを読み取りました（テスト用）",
          isCritical: false,
        },
      }));
    } else {
      setStatuses((s) => ({
        ...s,
        authToken: {
          status: "代替処理",
          detail: "トークンなし。代わりに匿名認証を試行します。",
          isCritical: false,
        },
      }));
    }

    // 4) initialize Firebase using standard Next.js env approach
    (async () => {
      if (typeof window === "undefined") {
        setStatuses((s) => ({
          ...s,
          init: {
            status: "失敗/欠落",
            detail: "SSR 環境のためクライアント初期化をスキップしました。",
            isCritical: true,
          },
        }));
        return;
      }

      // validate config
      if (!cfg.apiKey || !cfg.authDomain) {
        setStatuses((s) => ({
          ...s,
          init: {
            status: "失敗/欠落",
            detail:
              "Firebase config が不十分です。apiKey/authDomain が必要です。",
            isCritical: true,
          },
        }));
        return;
      }

      try {
        const app = getApps().length === 0 ? initializeApp(cfg) : getApp();
        setStatuses((s) => ({
          ...s,
          init: {
            status: "読み取り成功",
            detail: "Firebase App が初期化されました。",
            isCritical: false,
          },
        }));

        // Auth
        const auth = getAuth(app);

        // Sign-in: prefer custom token if provided, otherwise anonymous
        try {
          if (initialToken) {
            await signInWithCustomToken(auth, initialToken);
            setStatuses((s) => ({
              ...s,
              auth: {
                status: "読み取り成功",
                detail: "Custom Token でサインインに成功しました。",
                isCritical: false,
              },
            }));
          } else {
            await signInAnonymously(auth);
            setStatuses((s) => ({
              ...s,
              auth: {
                status: "読み取り成功",
                detail: "匿名サインインに成功しました。",
                isCritical: false,
              },
            }));
          }

          // observe auth state for extra confirmation
          const unsub = onAuthStateChanged(auth, (user) => {
            if (user) {
              setStatuses((s) => ({
                ...s,
                auth: {
                  status: "認証済み",
                  detail: `uid=${user.uid} (${
                    user.isAnonymous ? "anonymous" : "authenticated"
                  })`,
                  isCritical: false,
                },
              }));
            } else {
              setStatuses((s) => ({
                ...s,
                auth: {
                  status: "未認証",
                  detail: "ユーザーはサインインしていません。",
                  isCritical: true,
                },
              }));
            }
          });

          // Firestore: basic get to ensure library is available
          try {
            const db = getFirestore(app);
            // don't perform reads/writes here; just check that object exists
            if (db) {
              setStatuses((s) => ({
                ...s,
                firestore: {
                  status: "読み取り成功",
                  detail: "Firestore インスタンスを取得しました。",
                  isCritical: false,
                },
              }));
            }
          } catch (e) {
            setStatuses((s) => ({
              ...s,
              firestore: {
                status: "失敗/欠落",
                detail: `Firestore の取得に失敗: ${String(e)}`,
                isCritical: true,
              },
            }));
          }

          // cleanup on unmount
          return () => {
            try {
              unsub();
            } catch (e) {
              // ignore
            }
          };
        } catch (authErr) {
          setStatuses((s) => ({
            ...s,
            auth: {
              status: "失敗/欠落",
              detail: `認証に失敗しました: ${String(authErr)}`,
              isCritical: true,
            },
          }));
        }
      } catch (initErr) {
        setStatuses((s) => ({
          ...s,
          init: {
            status: "失敗/欠落",
            detail: `初期化中にエラー: ${String(initErr)}`,
            isCritical: true,
          },
        }));
      }
    })();
  }, []);

  const overallError =
    statuses.config.isCritical ||
    statuses.init.isCritical ||
    statuses.auth.isCritical;

  return (
    <div className="min-h-screen flex items-start justify-center bg-gray-50 p-8 font-inter">
      <div className="w-full max-w-2xl bg-white p-8 rounded-2xl shadow-xl border border-gray-200">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-extrabold text-gray-900 mt-3">
            Firebase 環境診断ツール（next.js 16）
          </h1>
          <p className="text-gray-500 mt-1">
            process.env から読み取り、Firebase の初期化・認証・Firestore
            の取得まで試行します。
          </p>
        </div>

        <div
          className={`p-5 rounded-xl font-bold text-white text-center mb-8 ${
            overallError ? "bg-red-600" : "bg-green-600"
          }`}
        >
          <div className="flex items-center justify-center">
            <AlertTriangleIcon className="w-6 h-6 mr-3 text-white" />
            {overallError
              ? "エラーが発生しました。詳細を確認してください。"
              : "Firebase は正常に動作しています。"}
          </div>
        </div>

        <h2 className="text-xl font-semibold text-gray-700 mb-4 border-b pb-2">
          1. グローバル変数の読み込み
        </h2>
        <ul className="space-y-3 mb-8">
          <StatusItem
            label="__app_id"
            status={statuses.appId.status}
            detail={statuses.appId.detail}
            isCritical={statuses.appId.isCritical}
          />
          <StatusItem
            label="__firebase_config (JSON)"
            status={statuses.config.status}
            detail={statuses.config.detail}
            isCritical={statuses.config.isCritical}
          />
          <StatusItem
            label="__initial_auth_token"
            status={statuses.authToken.status}
            detail={statuses.authToken.detail}
            isCritical={statuses.authToken.isCritical}
          />
        </ul>

        <h2 className="text-xl font-semibold text-gray-700 mb-4 border-b pb-2">
          2. Firebase サービスの初期化と認証
        </h2>
        <ul className="space-y-3 mb-8">
          <StatusItem
            label="Firebase App / Firestore 初期化"
            status={statuses.init.status}
            detail={statuses.init.detail}
            isCritical={statuses.init.isCritical}
          />
          <StatusItem
            label="ユーザー認証状態 (Auth)"
            status={statuses.auth.status}
            detail={statuses.auth.detail}
            isCritical={statuses.auth.isCritical}
          />
          <StatusItem
            label="Firestore"
            status={statuses.firestore.status}
            detail={statuses.firestore.detail}
            isCritical={statuses.firestore.isCritical}
          />
        </ul>

        {statuses.config.isCritical && (
          <div className="bg-red-500 p-4 rounded-xl text-white mt-6 font-mono text-sm border-2 border-red-800 shadow-lg">
            <span className="font-semibold block text-lg mb-2">
              発生した根本原因のエラー:
            </span>
            <span className="break-all font-bold">
              {statuses.config.detail}
            </span>
            <p className="mt-3 text-sm">
              **【重要】** このツールは process.env (NEXT_PUBLIC_*)
              から読み取って初期化します。
              <br />
              `.env` を変更したら dev サーバーを再起動してください。
              <br />
              （例: <code>NPM</code> なら <code>npm run dev</code> 再起動）
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
